454	    expect(quotePremium(components("rune", 7))).toBe(198);
455	  });
456	  it("2 runes + 1 moonstone -> no block (different types), base 75 G -> premium 88 G", () => {
457	    expect(quotePremium([...components("rune", 2), ...components("moonstone", 1)])).toBe(88);
458	  });
459	  it("3 runes + 3 moonstones -> two blocks, base 120 G -> premium 137 G", () => {
460	    expect(quotePremium([...components("rune", 3), ...components("moonstone", 3)])).toBe(137);
461	  });
462	  it("newcomer cursed steel sword enchantment 3 -> 100 + 50 curse + 10 first = 160 + 5 -> premium 165 G", () => {
463	    expect(quotePremium([{ type: "sword", material: "steel", enchantment: 3, cursed: true }])).toBe(165);
464	  });
