466	    expect(quotePremium([{ type: "sword", enchantment: 5 }])).toBe(145);
467	  });
468	  it("cursed sword with exactly enchantment 5 -> both surcharges -> premium 195 G", () => {
469	    expect(quotePremium([{ type: "sword", enchantment: 5, cursed: true }])).toBe(195);
470	  });
471	  it("plain sword with enchantment 4 -> no high-enchantment surcharge -> premium 115 G", () => {
472	    expect(quotePremium([{ type: "sword", enchantment: 4 }])).toBe(115);
473	  });
474	  it("customer with 1 year -> no loyalty discount on sword -> premium 115 G", () => {
475	    expect(quotePremium([{ type: "sword" }], 1)).toBe(115);
476	  });
