512	  });
513	  it("rune (value 250 G), damage 200 G -> payout 100 G, remainingCap 400 G", () => {
514	    expect(claimResults([{ type: "rune" }], [{ itemType: "rune", amount: 200 }])).toEqual([
515	      { payout: 100, remainingCap: 400 },
516	    ]);
517	  });
518	  it("moonstone (value 250 G), damage 200 G -> payout 100 G, remainingCap 400 G", () => {
519	    expect(claimResults([{ type: "moonstone" }], [{ itemType: "moonstone", amount: 200 }])).toEqual([
520	      { payout: 100, remainingCap: 400 },
521	    ]);
522	  });
523	  it("damage below the deductible (sword, 50 G) -> payout 0 G, remainingCap 2000 G (reading: deductible never yields a negative payout)", () => {
524	    expect(claimResults([{ type: "sword" }], [{ itemType: "sword", amount: 50 }])).toEqual([
525	      { payout: 0, remainingCap: 2000 },
526	    ]);
527	  });
528	  it("steel sword enchantment 9, damage 1000 G -> 50% then deductible -> payout 400 G", () => {
529	    const sword = { type: "sword", material: "steel", enchantment: 9 };
530	    expect(claimResults([sword], [{ itemType: "sword", amount: 1000 }])).toEqual([
531	      { payout: 400, remainingCap: 1600 },
532	    ]);
533	  });
534	  it("dragon sword exactly enchantment 8, damage 1000 G -> payout 400 G", () => {
535	    const sword = { type: "sword", material: "dragon", enchantment: 8 };
536	    expect(claimResults([sword], [{ itemType: "sword", amount: 1000 }])).toEqual([
537	      { payout: 400, remainingCap: 1600 },
538	    ]);
539	  });
540	  it("dragon sword enchantment 9, damage 1000 G -> 50% rule wins -> payout 400 G", () => {
541	    const sword = { type: "sword", material: "dragon", enchantment: 9 };
542	    expect(claimResults([sword], [{ itemType: "sword", amount: 1000 }])).toEqual([
543	      { payout: 400, remainingCap: 1600 },
544	    ]);
545	  });
546	  it("dragon sword enchantment 5, damage 800 G -> full reimbursement -> payout 700 G", () => {
547	    const sword = { type: "sword", material: "dragon", enchantment: 5 };
548	    expect(claimResults([sword], [{ itemType: "sword", amount: 800 }])).toEqual([
549	      { payout: 700, remainingCap: 1300 },
550	    ]);
551	  });
552	  it("sword enchantment 8, damage 901 G -> 350.5 G rounded down -> payout 350 G", () => {
553	    expect(claimResults([{ type: "sword", enchantment: 8 }], [{ itemType: "sword", amount: 901 }])).toEqual([
554	      { payout: 350, remainingCap: 1650 },
555	    ]);
556	  });
557	  it("sword + amulet damaged 500 G and 300 G -> deductible per item -> payout 600 G, remainingCap 2600 G (cap 3200 G)", () => {
558	    const damages = [
559	      { itemType: "sword", amount: 500 },
560	      { itemType: "amulet", amount: 300 },
561	    ];
562	    expect(claimResults([{ type: "sword" }, { type: "amulet" }], damages)).toEqual([
563	      { payout: 600, remainingCap: 2600 },
